{
  "name": "Document Approval Workflow",
  "description": "Standard document review and approval process",
  "code": "doc_approval_postmanac_temp2",
  "entity_type": "document",
  "status": "draft",
  "is_default": false,
  "source_module": ["platform"],
  "source_module_id": [],
  "config": {},
  "steps": [
    {
        "step_code": "file-upload",
        "name":"File Upload",
        "sequence": 1,
        "step_type": "initial",
        "assignee": {
            "type": "role",
            "role":["Manager"]
        },
        "available_actions": [
            "submit"
        ]
    },
    {
        "step_code": "extract-data",
        "name":"Extract Data",
        "sequence": 2,
        "step_type": "task",
        "assignee": {
            "type": "role",
            "role":["Manager"]
        },
        "available_actions": [
            "view document"
        ]
    },
    {
        "step_code": "edit",
        "name":"Edit File",
        "sequence": 3,
        "step_type": "task",
        "assignee": {
            "type": "role",
            "role":["Manager"]
        },
        "available_actions": [
            "edit"
        ]
    },
    {
        "step_code": "review",
        "name":"Review File",
        "sequence": 3,
        "step_type": "task",
        "assignee": {
            "type": "role",
            "role":["Quality Analyst","Manager"]
        },
        "available_actions": [
            "approve",
            "reject"
        ]
    },
    {
      "step_code": "approved",
      "name": "Approved",
      "sequence": 4,
      "step_type": "terminal",
      "requires_signature": false,
      "requires_comment": false,
      "available_actions": []
    },
    {
      "step_code": "rejected",
      "name": "Rejected",
      "sequence": 5,
      "step_type": "terminal",
      "requires_signature": false,
      "requires_comment": false,
      "available_actions": []
    }
  ],
  "transitions": [
    {
      "from_step": "file-upload",
      "to_step": "extract-data",
      "action": "submit"
    //   ,
    //   "name": "Submit for Review",
    //   "priority": 0,
    //   "requires_signature": false,
    //   "requires_comment": false
    },
     {
      "from_step": "extract-data",
      "to_step": "edit",
      "action": "view document",
      "name": "Extract data",
      "priority": 0,
      "requires_signature": false,
      "requires_comment": false
    },
    {
      "from_step": "edit",
      "to_step": "approved",
      "action": "edit",
      "name": "Edit Document",
      "priority": 0,
      "requires_signature": false,
      "requires_comment": false,
      "signature_meaning": "I edit this document"
    },
     {
      "from_step": "review",
      "to_step": "approved",
      "action": "approve",
      "name": "Approve Document",
      "priority": 0,
      "requires_signature": false,
      "requires_comment": false,
      "signature_meaning": "I approve this document"
    },
    {
      "from_step": "review",
      "to_step": "rejected",
      "action": "reject",
      "name": "Reject Document",
      "priority": 1,
      "requires_signature": false,
      "requires_comment": true
    }
  ]
}

{
  "task_id": "{{reject_task_id}}",
  "action": "reject",
  "comments": "Document does not meet quality standards - revision required"
}
